+        if (size <= 0) {
+            return Integer.MAX_VALUE;
+        }
+        if (size == 1) {
+            size--;
+            return heap[0];
+        }
+
+        int root = heap[0];
+        heap[0] = heap[size - 1];
+        size--;
+        heapify(0);
+        return root;
+    }
+
+    public void deleteKey(int i) {
+        decreaseKey(i, Integer.MIN_VALUE);
+        extractMin();
+    }
+
+    private void heapify(int i) {
+        int l = left(i);
+        int r = right(i);
+        int smallest = i;
+
+        if (l < size && heap[l] < heap[smallest]) {
+            smallest = l;
+        }
+        if (r < size && heap[r] < heap[smallest]) {
+            smallest = r;
+        }
+        if (smallest != i) {
+            swap(i, smallest);
+            heapify(smallest);
+        }
+    }
